class Solution:
    def partitionString(self, s):
        seen = set(); cur = []; res = []
        for ch in s:
            cur.append(ch)
            t = ''.join(cur)
            if t not in seen:
                res.append(t); seen.add(t); cur = []
        return res

c.cpp:
class Solution {
public:
    vector<string> partitionString(string s) {
        unordered_set<string> seen;
        vector<string> res;
        string cur;
        for (char ch : s) {
            cur += ch;
            if (!seen.count(cur)) { res.push_back(cur); seen.insert(cur); cur.clear(); }
        }
        return res;
    }
};

c.java:
class Solution {
    public List<String> partitionString(String s) {
        Set<String> seen = new HashSet<>();
        List<String> res = new ArrayList<>();
        StringBuilder cur = new StringBuilder();
        for (char ch : s.toCharArray()) {
            cur.append(ch);
            String t = cur.toString();
            if (seen.add(t)) res.add(t), cur.setLength(0);
        }
        return res;
    }
}

